
/* ===================== GLX-C30 (v0.9.30): hi-res in-world textures. Root cause: the newer blocks were 64-128px tiles, and the v0.9.29 swap was overwritten by the late async load, so the world kept the 64px tile while icons used the new art. ===================== */
const TEX30 = {"red_sandstone": "data:image/jpeg;base64,", "harl": "data:image/jpeg;base64,", "slate_roof": "data:image/jpeg;base64,", "tile_roof": "data:image/jpeg;base64,", "asphalt": "data:image/jpeg;base64,", "pavement": "data:image/jpeg;base64,", "white_stone": "data:image/jpeg;base64,", "concrete": "data:image/jpeg;base64,", "kerb": "data:image/jpeg;base64,", "road_white": "data:image/jpeg;base64,", "lamp_post": "data:image/jpeg;base64,", "lamp": "data:image/jpeg;base64,", "fence": "data:image/png;base64,", "railing": "data:image/png;base64,", "cairngorm_ore": "data:image/jpeg;base64,", "silver_ore": "data:image/jpeg;base64,", "obsidian": "data:image/jpeg;base64,", "br_wallpaper": "data:image/jpeg;base64,", "br_carpet": "data:image/jpeg;base64,", "br_ceiling": "data:image/jpeg;base64,", "br_light": "data:image/jpeg;base64,", "br_pillar": "data:image/jpeg;base64,", "br_window": "data:image/jpeg;base64,", "br_white": "data:image/jpeg;base64,", "br_grass": "data:image/jpeg;base64,", "br_paving": "data:image/jpeg;base64,", "br_painting": "data:image/jpeg;base64,", "gravel": "data:image/jpeg;base64,", "portal": "data:image/jpeg;base64,", "hellrock": "data:image/jpeg;base64,", "soulsand": "data:image/jpeg;base64,", "magma": "data:image/jpeg;base64,", "glowrock": "data:image/jpeg;base64,", "hellbrick": "data:image/jpeg;base64,", "hbedrock": "data:image/jpeg;base64,", "qlantern": "data:image/jpeg;base64,", "peatbrick": "data:image/jpeg;base64,", "rcarpet": "data:image/jpeg;base64,", "tapestry": "data:image/jpeg;base64,", "bookshelf": "data:image/jpeg;base64,"};
(function hiRes30() {
  const thumb = c => { const s = document.createElement('canvas'); s.width = s.height = 96; const g = s.getContext('2d'); g.imageSmoothingQuality = 'high'; g.drawImage(c, 0, 0, 96, 96); return s.toDataURL('image/jpeg', 0.85); };
  const css = [], st = document.createElement('style'); document.head.appendChild(st);
  const mine = {};
  const fit = img => { // high-quality downscale (halving steps) to TEXSIZE
    let c = img, w = img.width; while (w / 2 >= TEXSIZE) { const n = document.createElement('canvas'); n.width = n.height = w / 2; const g = n.getContext('2d'); g.imageSmoothingQuality = 'high'; g.drawImage(c, 0, 0, w / 2, w / 2); c = n; w /= 2; }
    if (c === img) { const n = document.createElement('canvas'); n.width = n.height = Math.min(TEXSIZE, w); n.getContext('2d').drawImage(img, 0, 0, n.width, n.height); c = n; } return c; };
  const apply = k => { const c = mine[k], t = texCache[k]; if (!c || !t) return false; if (t.image !== c) { t.image = c; t.anisotropy = TEXANISO; t.needsUpdate = true; } return true; };
  for (const k in TEX30) {
    TEX[k] = TEX30[k]; const img = new Image();
    img.onload = () => { const c = fit(img); mine[k] = c; texImg[k] = c; const s = document.createElement('canvas'); s.width = s.height = 1; const sg = s.getContext('2d'); sg.drawImage(c, 0, 0, 1, 1); const d = sg.getImageData(0, 0, 1, 1).data; AVG[k] = (d[0] << 16) | (d[1] << 8) | d[2];
      apply(k); css.push('.ic-' + k + '{background-image:url(' + thumb(c) + ') !important}'); st.textContent = css.join('\n'); };
    img.src = TEX30[k];
  }
  // keep re-applying until every original async load has finished (they used to overwrite the hi-res tile)
  let n = 0; const iv = setInterval(() => { for (const k in mine) apply(k); if (++n > 150 || (texDone >= texTotal && Object.keys(mine).length === Object.keys(TEX30).length && n > 10)) { clearInterval(iv); for (const k in mine) apply(k); } }, 200);
  window.__tex30 = mine;
  // every block texture: trilinear + high anisotropy
  for (const k in texCache) { const t = texCache[k]; t.minFilter = THREE.LinearMipmapLinearFilter; t.magFilter = THREE.LinearFilter; t.generateMipmaps = true; if (t.anisotropy < TEXANISO) { t.anisotropy = TEXANISO; t.needsUpdate = !!t.image; } }
  // blocks with no inventory icon fall back to their own face texture
  for (const id in NAMES) { if (ICONS[id] || ICON_KEY[id] || !FACES[id]) continue; const f = FACES[id]; ICON_KEY[id] = Array.isArray(f) ? (f[2] || f[0]) : f; }
  const icss = document.createElement('style'); document.head.appendChild(icss);
  const have = new Set(); [...document.styleSheets].forEach(s => { try { [...s.cssRules].forEach(r => { const m = /^\.ic-([a-z0-9_]+)$/.exec(r.selectorText || ''); if (m) have.add(m[1]); }); } catch (_) {} });
  const fill = () => { const out = []; for (const id in ICON_KEY) { const k = ICON_KEY[id]; if (have.has(k) || TEX30[k] || !texImg[k]) continue; have.add(k); out.push('.ic-' + k + '{background-image:url(' + thumb(texImg[k]) + ')}'); } if (out.length) icss.textContent += out.join('\n'); };
  let m2 = 0; const iv2 = setInterval(() => { fill(); if (++m2 > 40) clearInterval(iv2); }, 500);
})();
